const MemoryRecordSchema = @import("memory_record_schema.zig").MemoryRecordSchema;
const EpisodicReflectionConfigurationInput = @import("episodic_reflection_configuration_input.zig").EpisodicReflectionConfigurationInput;

/// Input for creating an episodic memory strategy.
pub const EpisodicMemoryStrategyInput = struct {
    /// The description of the episodic memory strategy.
    description: ?[]const u8 = null,

    /// Schema for metadata fields on records generated by this strategy.
    memory_record_schema: ?MemoryRecordSchema = null,

    /// The name of the episodic memory strategy.
    name: []const u8,

    /// The namespaces for which to create episodes.
    namespaces: ?[]const []const u8 = null,

    /// The namespaceTemplates for which to create episodes.
    namespace_templates: ?[]const []const u8 = null,

    /// The configuration for the reflections created with the episodic memory
    /// strategy.
    reflection_configuration: ?EpisodicReflectionConfigurationInput = null,

    pub const json_field_names = .{
        .description = "description",
        .memory_record_schema = "memoryRecordSchema",
        .name = "name",
        .namespaces = "namespaces",
        .namespace_templates = "namespaceTemplates",
        .reflection_configuration = "reflectionConfiguration",
    };
};
